var items=$input.all(); var out=[];
for(var r=0;r<items.length;r++){
 var conv=items[r].json.simulated_conversation||[];
 var q=[], tools=[];
 for(var i=0;i<conv.length;i++){ var t=conv[i]; if(t.role==="agent" && t.message) q.push(t.message); if(t.tool_calls){ for(var j=0;j<t.tool_calls.length;j++){ var p={}; try{p=JSON.parse(t.tool_calls[j].params_as_json||"{}");}catch(e){} tools.push(p); } } }
 out.push({ json: { idx:r+1, agent_turns:q, tool_params:tools } });
}
return out;
